package com.hospital.system.repository; import com.hospital.system.model.Department; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; @Repository public class DepartmentRepository { private final JdbcTemplate db; public DepartmentRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Department> m=(r,n)->{Department d=new Department();d.departmentId=r.getLong("department_id");d.departmentName=r.getString("department_name");d.description=r.getString("description");return d;}; public List<Department> all(){return db.query("SELECT * FROM department ORDER BY department_name",m);} public Optional<Department> one(Long id){return db.query("SELECT * FROM department WHERE department_id=?",m,id).stream().findFirst();} public int add(Department d){return db.update("INSERT INTO department(department_name,description) VALUES(?,?)",d.departmentName,d.description);} public int update(Long id,Department d){return db.update("UPDATE department SET department_name=?,description=? WHERE department_id=?",d.departmentName,d.description,id);} public int delete(Long id){return db.update("DELETE FROM department WHERE department_id=?",id);} }
